UPDATE account SET frequency = 'weekly'
WHERE account_id IN (
    SELECT d.account_id FROM disp d JOIN client c ON c.client_id = d.client_id
    WHERE d.type = 'owner' AND c.birth_date < '1920-01-01'
);

UPDATE account SET frequency = 'weekly'
WHERE account_id IN (
    SELECT d.account_id FROM disp d JOIN client c ON c.client_id = d.client_id
    WHERE c.birth_date < '1920-01-01'
);

UPDATE card SET type = 'classic'
WHERE type = 'junior' AND disp_id IN (
    SELECT d.disp_id FROM disp d JOIN client c ON c.client_id = d.client_id
    WHERE c.birth_date <= '1977-12-31'
);

DELETE FROM standing_order
WHERE purpose = 'leasing'
  AND account_id IN (SELECT account_id FROM account WHERE status = 'closed');

UPDATE card SET type = 'gold'
WHERE type = 'classic'
  AND disp_id IN (
      SELECT d.disp_id FROM disp d JOIN account a ON a.account_id = d.account_id
      WHERE a.district_id = 1
  )
  AND disp_id NOT IN (
      SELECT d.disp_id FROM disp d JOIN loan l ON l.account_id = d.account_id
      WHERE l.status = 'running_in_debt'
  );

UPDATE trans SET purpose = 'interest'
WHERE account_id = 7418 AND purpose = 'penalty_interest'
  AND date BETWEEN '1997-01-01' AND '1997-06-30';

UPDATE trans SET purpose = 'interest'
WHERE account_id = 7418 AND purpose = 'penalty_interest'
  AND date >= '1997-1-1' AND date <= '1997-6-30';

UPDATE account SET status = 'closed', closed_on = '1998-12-31'
WHERE district_id = 1
  AND account_id NOT IN (SELECT account_id FROM trans WHERE date >= '1998-01-01');
